export const useTools = (params: ToolsParams = {}) => {
  const { page = 1, limit = 10, ...rest } = params
  return useQuery<Tool[]>({
    queryKey: ['tools', { page, limit, ...rest }],
    queryFn: () => api.get('/tools', { _page: page, _limit: limit, ...rest }),
  })
}
